import pathlib,json,re,hashlib
r=pathlib.Path('.')
e=json.loads((r/'tools/obj/rea/vsconfig-import-result.json').read_text(encoding='utf-8-sig'));n=e['normalized_result']
assert n['summary']['imported_methods']==47 and not n['executed']
d=json.loads((r/'tools/obj/rea/vsconfig-decompiler.json').read_text(encoding='utf-8-sig'))
for m in d['Methods']:assert hashlib.sha256(pathlib.Path(m['SourcePath']).read_bytes()).hexdigest().upper()==m['SourceSHA256']
props=re.findall(r'PropertyName == "([^"]+)"',(r/'tools/obj/rea/vsconfig-decompiled/0x06000017.cs').read_text())
a={'evidence_id':e['evidence_id'],'parentEvidence':n['static_observation']['evidence_id'],'subject':e['subject'],'methodCount':47,'sourceHashMatches':47,'unresolvedTypeWarnings':sum(x['Warnings'] for x in d['Methods']),'executedOriginal':False,'scope':'Entire managed inspection VS configuration adapter reconstruction; native general parser not established','changeEventProperties':props,'findings':[{'token':'0x0600001d','fact':'Cache invalidation clears project options, sanitize, directory-exists, unavailable-file-tool, makefile settings and project-file caches, then increments generation under shared lock.'},{'token':'0x06000017','fact':'Every ItemPropertyChange2 clears caches; SomethingChanged only for active configuration and listed property names.'},{'token':'0x06000019','fact':'Makefile cache key projectPath+NUL+configuration; compute outside lock, admit only unchanged generation.'},{'token':'0x0600001a','fact':'Microsoft.Build.Evaluation loads project with Configuration/Platform globals; ClCompile/ClInclude evaluated metadata yields file forced includes, extra include directories, definitions; first duplicate full path wins with OrdinalIgnoreCase; UnloadProject in finally.'},{'token':'0x0600001c','fact':'Per-file makefile lookup overrides forced includes, directories and preprocessor definitions; exceptions logged and caught.'},{'token':'0x06000012','fact':'Sanitize cache key combines include text, project directory and relative-path flag; cache-generation check controls admission.'},{'token':'0x0600000e','fact':'Evaluated rule CompileAs distinguishes C/C++; non-C LanguageStandard maps14/17/20/latest99; AdditionalOptions can override standard.'}],'comparisonCases':['Change active/inactive configuration properties and observe cache invalidation vs reparse event','Conditional evaluated per-file metadata in makefile ClCompile/ClInclude items','Duplicate file paths with differing case','Invalidate while a cache miss calculation is pending','CompileAsC vs CompileAsCpp with .c extension fallback','LanguageStandard versus trailing /std additional options','MSBuild missing project/invalid path/exception cleanup'],'comparisonState':'Original runtime comparisons unexecuted','limitations':n['limitations']+['47 managed methods reconstructed does not imply all algorithms or behavior proven.','No original MSBuild project evaluation or VS event injection executed.','Not proof of C# support or whole native semantic indexing.']}
(r/'docs/validation/rea/vs-configuration-reconstruction-summary.json').write_text(json.dumps(a,ensure_ascii=False,indent=2),encoding='utf-8')
p=r/'tools/BuildParitySpec.py';s=p.read_text(encoding='utf-8');needle="(r/'docs/integrated-spec.md').write_text"
insert="configurationPath=r/'docs/validation/rea/vs-configuration-reconstruction-summary.json'\nif configurationPath.exists():\n config=json.loads(configurationPath.read_text(encoding='utf-8'))\n data['vsConfigurationEvidence']='rea/vs-configuration-reconstruction-summary.json'\n (r/'docs/validation/integrated-spec.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')\n lines+=['','## VS 프로젝트·파일 구성 전체 managed adapter','','[REA 재구성 근거](validation/rea/vs-configuration-reconstruction-summary.json): 관리형 VS 통합 DLL의47개 메서드를 token/signature/IL로 대조하고 재구성 파일47개 hash를 검증했습니다. 이는 검사 구성 adapter의 정적 분석 범위이며 일반 native parser 전체 구현이 아닙니다.','']\n lines+=['- '+x['token']+': '+x['fact'] for x in config['findings']]\n lines+=['','활성 구성 변경 통지 대상: '+', '.join(config['changeEventProperties'])+'.','', '원본 비교 대기: '+'; '.join(config['comparisonCases'])+'.','', 'MSBuild 실제 평가·VS property 변경 이벤트·취소/수명 runtime 검증은 미실행입니다. 제품 코드는 추가하지 않았습니다.']\n"
if insert not in s:s=s.replace(needle,insert+needle,1)
p.write_text(s,encoding='utf-8')
print('REA47 methods and47 reconstruction hashes verified; unresolved type warnings',a['unresolvedTypeWarnings'],'change properties',len(props))
